ins\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"count\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_count\", ret: \"flint\", nullable: FALSE}", "        if name == \"index\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_index_of\", ret: \"flint\", nullable: TRUE}", "        if name == \"join\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"list_join\", ret: \"str\", nullable: FALSE}", "    elif b == \"dict\":", "        if name == \"add\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"str\", a2: \"any\", rt: \"dict_add\", ret: \"NONE\", nullable: FALSE}", "        if name == \"take\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_take\", ret: \"any\", nullable: TRUE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_remove\", ret: \"bool\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"merge\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"dict\", a2: \"any\", rt: \"dict_merge\", ret: \"dict\", nullable: FALSE}", "    elif b == \"expect\":", "        if name == \"equals\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_equals\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_true\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_true\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_false\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_false\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_none\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_none\", ret: \"NONE\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_contains\", ret: \"NONE\", nullable: FALSE}", "    return {ok: FALSE}", "", "func is_reserved(str name) -> bool:", "    if is_builtin(name) OR name == \"show\" OR name == \"show_err\" OR name == \"input\" OR name == \"Error\":", "        return TRUE", "    if name == \"error\" OR name == \"ANY_ERROR\":", "        return TRUE", "    # Методы типов — тоже занятые имена: `add`, `take`, `contains`, `text` и т.д.", "    return method_info(\"str\", name)[ok] OR method_info(\"list\", name)[ok] OR method_info(\"dict\", name)[ok] OR method_info(\"expect\", name)[ok] OR name == \"text\"", "", "# Имена функций могут совпадать с методами типов: вызов `x.add(...)` всё равно", "# разрешается как метод, а отдельная функция `add(...)` — как обычная.", "func is_func_name_free(str name) -> bool:", "    if is_builtin(name) OR name == \"show\" OR name == \"show_err\" OR name == \"input\" OR name == \"Error\":", "        return FALSE", "    if name == \"error\" OR name == \"ANY_ERROR\":", "        return FALSE", "    return TRUE", "", "# Встроенная модель Error: схема известна компилятору, объект создаёт рантайм.", "func error_schema() -> dict:", "    dict fields = {cat: \"str\", msg: \"str\", file: \"str\", line: \"flint\", col: \"flint\"}", "    dict consts = {}", "    consts.add(\"cat\", TRUE)", "    consts.add(\"msg\", TRUE)", "    consts.add(\"file\", TRUE)", "    consts.add(\"line\", TRUE)", "    consts.add(\"col\", TRUE)", "    dict meth = {}", "    meth.add(\"text\", {params: [], ret: \"str\", ret_nullable: FALSE, line: 1, col: 1})", "    return {name: \"Error\", model_fields: {}, field_types: fields, consts: consts, init_fields: {}, params: [], param_types: {}, methods: meth, method_order: [\"text\"], ctor: NONE, order: [], field_order: []}", "", "# Категории, которые рантайм может положить в error.cat.", "func is_error_category(str c) -> bool:", "    if c == \"ANY_ERROR\" OR c == \"ARGCOUNT_ERROR\" OR c == \"ASSERT_ERROR\":", "        return TRUE", "    if c == \"CONST_ERROR\" OR c == \"EXPECT_ERROR\" OR c == \"FILE_ERROR\":", "        return TRUE", "    if c == \"NAME_ERROR\" OR c == \"RUNTIME_ERROR\" OR c == \"TYPE_ERROR\":", "        return TRUE", "    if c == \"TYPE_MISMATCH_ERROR\" OR c == \"VALUE_ERROR\":", "        return TRUE", "    if c == \"PANIC_ERROR\":", "        return TRUE", "    return FALSE", "", "func is_scalar_type(str t) -> bool:", "    return t == \"str\" OR t == \"flint\" OR t == \"bool\"", "", "func is_model_type(dict st, str t) -> bool:", "    dict ms = st[models]", "    return ms.contains(t)", "", "func model_schema(dict st, str t) -> dict:", "    dict ms = st[models]", "    return ms.take(t)", "", "func check_field_name(dict st, dict tok, str nm):", "    if is_reserved(nm):", "        fail(st, tok, \"NAME_ERROR\", \"free field name\", cat([\"reserved '\", nm, \"'\"]))", "        return:", "", "# Регистрирует экземплярное поле в схеме. new=FALSE — поле уже было.", "func add_model_field(dict st, dict m, dict tok, str nm, str fty, bool computed):", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict cs = m[consts]", "    dict initf = m[init_fields]", "    dict methods = m[methods]", "    if mf.contains(nm) OR ft.contains(nm) OR methods.contains(nm):", "        fail(st, tok, \"REDECLARE_ERROR\", \"unique field/method name\", cat([\"name '\", nm, \"' is already declared\"]))", "        return:", "    ft.add(nm, fty)", "    list fo = m[field_order]", "    fo.add(nm)", "    if is_const_name(nm):", "        cs.add(nm, TRUE)", "    if computed AND NOT is_const_name(nm):", "        initf.add(nm, TRUE)", "", "func parse_type_name(dict st) -> str:", "    dict t = tk(st)", "    if t[type] == \"name\" AND is_model_type(st, t[value]):", "        advance(st)", "        return t[value]", "    if tok_is(t, \"kw\", \"NONE\"):", "        advance(st)", "        return \"NONE\"", "    return parse_type_spec(st)", "", "# Обычная строка без интерполяции: для ключей dict и сообщения panic.", "func plain_string_of(dict st, dict t) -> str:", "    list parts = t[parts]", "    list buf = []", "    for p0 in parts:", "        dict p = p0", "        if p[kind] != \"text\":", "            fail(st, t, \"TYPE_ERROR\", \"plain string\", \"interpolated string\")", "            return \"\"", "        buf.add(p[value])", "    return buf.join(\"\")", "", "func dirname(str p) -> str:", "    flint i = len(p) - 1", "    while i >= 0:", "        if p[i] == \"/\":", "            if i == 0:", "                return \"/\"", "            return p[..i]", "        i -= 1", "    return \".\"", "", "# Соответствует ли литерал параметризованному типу.", "func literal_ok(dict st, dict e, str spec) -> bool:", "    str base = base_type(spec)", "    list targs = type_args(spec)", "    if base == \"list\" OR base == \"froz\":", "        if e[k] != \"list\":", "            return FALSE", "        list its = e[items]", "        for it0 in its:", "            dict it = it0", "            bool ok = FALSE", "            for a0 in targs:", "                str want = base_type(a0)", "                if want == \"any\" OR base_type(it[t]) == want:", "                    ok = TRUE", "            if NOT ok:", "                return FALSE", "        return TRUE", "    if base == \"dict\":", "        if e[k] != \"dict\":", "            return FALSE", "        list prs = e[pairs]", "        str want_key = targs[0]", "        str want_val = \"\"", "        if len(targs) == 2:", "            want_val = base_type(targs[1])", "        for pd0 in prs:", "            dict pd = pd0", "            if pd[ktype] != want_key:", "                return FALSE", "            dict pv = pd[value]", "            if want_val != \"\" AND want_val != \"any\" AND base_type(pv[t]) != want_val:", "                return FALSE", "        return TRUE", "    return FALSE", "", "# В новой модели условием может быть только bool (и NONE как ложь).", "func check_condition(dict st, dict e, dict tok):", "    str et = base_type(e[t])", "    if et != \"bool\" AND et != \"NONE\" AND et != \"any\":", "        fail(st, tok, \"TYPE_ERROR\", \"bool condition (TRUE, FALSE or NONE)\", e[t])", "", "# Prelude объявляет функции для проверки типов до разбора пользовательского кода.", "func add_prelude_func(dict st, str name, str lua, list ptypes, str ret):", "    list params = []", "    for pt0 in ptypes:", "        str pt = pt0", "        params.add({name: \"arg\", type: pt, line: 1, col: 1})", "    dict info = {params: params, ret: ret, ret_nullable: FALSE, inferring: FALSE}", "    dict funcs = st[funcs]", "    funcs.add(name, info)", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "", "func add_prelude(dict st):", "    add_prelude_func(st, \"prelude_cat\", \"prelude_f_1\", [\"str\"], \"str\")", "    add_prelude_func(st, \"path_join\", \"prelude_f_2\", [\"str\", \"str\"], \"str\")", "    add_prelude_func(st, \"now_ms\", \"prelude_f_3\", [], \"flint\")", "    add_prelude_func(st, \"parse_args\", \"prelude_f_4\", [], \"dict\")", "    add_prelude_func(st, \"parse_csv\", \"prelude_f_5\", [\"str\"], \"list\")", "    add_prelude_func(st, \"parse_json\", \"prelude_f_6\", [\"str\"], \"dict\")", "", "func mangle_var(dict st, str name) -> str:", "    st.add(\"vcounter\", st[vcounter] + 1)", "    str lua = cat([\"v_\", str(st[vcounter])])", "    dict names = st[names]", "    names.add(name, lua)", "    return lua", "", "func mangle_func(dict st, str name) -> str:", "    st.add(\"fcounter\", st[fcounter] + 1)", "    str lua = cat([\"f_\", str(st[fcounter])])", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "    return lua", "", "# Имена внутри namespace хранятся с префиксом \"ns.\".", "func decl_key(dict st, str name) -> str:", "    str pref = st[ns_prefix]", "    if pref == \"\":", "        return name", "    return cat([pref, name])", "", "func read_key(dict st, str name) -> str:", "    str pref = st[ns_read_prefix]", "    if pref == \"\":", "        return name", "    return cat([pref, name])", "", "func is_declared_name(dict st, str name) -> bool:", "    dict dns = st[names]", "    if dns.contains(name):", "        return TRUE", "    dict dfs = st[funcs]", "    if dfs.contains(name):", "        return TRUE", "    dict dvs = st[vars]", "    if dvs.contains(name):", "        return TRUE", "    dict dgs = st[gvars]", "    if dgs.contains(name):", "        return TRUE", "    return FALSE", "", "# Читает имя, допуская краткую форму внутри namespace и ns.name снаружи.", "func consume_name(dict st, str what) -> dict:", "    dict nt = expect_tok(st, \"name\", \"\", what)", "    if NOT (st[err] is NONE):", "        return {}", "    str nm = nt[value]", "    str key = read_key(st, nm)", "    if is_declared_name(st, key) AND NOT tok_is(tk(st), \"op\", \".\"):", "        return {name: key, tok: nt}", "    if tok_is(tk(st), \"op\", \".\"):", "        dict dt = advance(st)", "        dict mt = tk(st)", "        if mt[type] == \"name\":", "            str cand = cat([nm, \".\", mt[value]])", "            if is_declared_name(st, cand):", "                advance(st)", "                return {name: cand, tok: nt}", "        st.add(\"pos\", st[pos] - 1)", "    return {name: nm, tok: nt}", "", "func name_assign_op(dict st) -> str:", "    dict n1 = token_at(st, st[pos] + 1)", "    if n1[type] != \"op\":", "        return \"\"", "    if n1[value] == \"=\" OR is_compound(n1[value]):", "        return n1[value]", "    if n1[value] != \".\":", "        return \"\"", "    dict n2 = token_at(st, st[pos] + 2)", "    if n2[type] != \"name\":", "        return \"\"", "    dict n0 = token_at(st, st[pos])", "    str cand = cat([n0[value], \".\", n2[value]])", "    if NOT is_declared_name(st, cand):", "        return \"\"", "    dict n3 = token_at(st, st[pos] + 3)", "    if n3[type] == \"op\" AND (n3[value] == \"=\" OR is_compound(n3[value])):", "        return n3[value]", "    return \"\"", "", "func e_nullable(dict e) -> bool:", "    if e.contains(\"nullable\"):", "        return e[nullable]", "    return FALSE", "", "# ---------- парсер: выражения ----------", "", "func shift_token_pos(dict t, flint dl, flint dc) -> bool:", "    if NOT t.contains(\"line\"):", "        return TRUE", "    flint old = t[line]", "    t.add(\"line\", old + dl)", "    if old == 1:", "        t.add(\"col\", t[col] + dc)", "    if t.contains(\"parts\"):", "        list ps = t[parts]", "        flint pi = 0", "        while pi < len(ps):", "            shift_token_pos(ps[pi], dl, dc)", "            pi += 1", "    return TRUE", "", "func template_state(dict st, dict p) -> dict:", "    dict lx = lex(p[src], st[path])", "    list ts = lx[tokens]", "    dict e0 = NONE", "    if NOT (lx[err] is NONE):", "        dict le = lx[err]", "        flint eline = p[line] + le[line] - 1", "        flint ecol = le[col]", "        if le[line] == 1:", "            ecol = p[col] + le[col] - 1", "        e0 = {cat: \"SYNTAX_ERROR\", line: eline, col: ecol, msg: le[msg], path: st[path]}", "    flint i = 0", "    while i < len(ts):", "        dict t2 = ts[i]", "        shift_token_pos(t2, p[line] - 1, p[col] - 1)", "        i += 1", "    return {toks: ts, pos: 0, path: st[path], vars: st[vars], nullable: st[nullable], maybe_unset: st[maybe_unset], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], for_names: st[for_names], funcs: st[funcs], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], block_depth: st[block_depth], loop_depth: st[loop_depth], cond_depth: st[cond_depth], err: e0, errors: st[errors], broken: st[broken], current_model: st[current_model], names: st[names], fnames: st[fnames], vcounter: st[vcounter], fcounter: st[fcounter], models: st[models], model_ctx: st[model_ctx]}", "", "func parse_expr(dict st, flint min_bp) -> dict:", "    if NOT (st[err] is NONE):", "        return {}", "    dict t = tk(st)", "    str ty = t[type]", "    dict e = {}", "    dict ptok = NONE", "    str pfn = \"\"", "", "    if ty == \"number\":", "        advance(st)", "        e = {k: \"num\", value: t[value], raw: t[raw], t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"string\":", "        advance(st)", "        ptok = t", "    elif ty == \"kw\" AND t[value] == \"TRUE\":", "        advance(st)", "        e = {k: \"bool\", value: TRUE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"FALSE\":", "        advance(st)", "        e = {k: \"bool\", value: FALSE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"NONE\":", "        advance(st)", "        e = {k: \"none\", t: \"NONE\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"PI\":", "        advance(st)", "        e = {k: \"const\", name: \"PI\", t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"self\":", "        dict mctx = st[model_ctx]", "        if mctx is NONE:", "            fail(st, t, \"SCOPE_ERROR\", \"'self' inside a model\", \"'self' outside a model\")", "            return {}", "        advance(st)", "        if tok_is(tk(st), \"op\", \"(\"):", "            advance(st)", "            list snames = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict snt = expect_tok(st, \"name\", \"\", \"parameter name in self(...)\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    snames.add(snt)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            e = {k: \"self_init\", names: snames, t: \"NONE\", line: t[line], col: t[col]}", "        else:", "            e = {k: \"var\", name: \"self\", lua: \"self\", t: mctx[model_name], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_model_type(st, t[value]) AND peek_value(st) == \"(\":", "        str cmn = t[value]", "        dict cms = model_schema(st, cmn)", "        dict ccons = cms[ctor]", "        if ccons is NONE:", "            fail(st, t, \"NAME_ERROR\", cat([\"declared construct of '\", cmn, \"'\"]), \"model without construct\")", "            return {}", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list cmargs = []", "        if NOT tok_is(tk(st), \"op\", \")\"):", "            while TRUE:", "                dict cma = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                cmargs.add(cma)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        list cmparams = ccons[params]", "        if len(cmargs) != len(cmparams):", "            fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(cmparams)), \" argument(s) to '\", cmn, \"'\"]), cat([str(len(cmargs)), \" argument(s)\"]))", "            return {}", "        list cmpt = []", "        flint cmi = 0", "        while cmi < len(cmargs):", "            dict cma2 = cmargs[cmi]", "            dict cmp = cmparams[cmi]", "            cmpt.add(cmp[type])", "            if NOT coercion_ok(cma2, cmp[type]):", "                fail(st, {line: cma2[line], col: cma2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cmi + 1), \" of '\", cmn, \"' to be \", cmp[type]]), cma2[t])", "                return {}", "            cmi += 1", "        e = {k: \"model_new\", mname: cmn, args: cmargs, ptypes: cmpt, t: cmn, line: t[line], col: t[col]}", "    elif (ty == \"kw\" OR ty == \"name\") AND is_builtin(t[value]) AND peek_value(st) == \"(\":", "        str bn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list bargs = []", "        if bn == \"map\" OR bn == \"filter\" OR bn == \"reduce\":", "            dict hcoll = parse_expr(st, 0)", "            if NOT (st[err] is NONE):", "                return {}", "            bargs.add(hcoll)", "            expect_tok(st, \"op\", \",\", \"','\")", "            if NOT (st[err] is NONE):", "                return {}", "            dict hft = expect_tok(st, \"name\", \"\", \"function name\")", "            if NOT (st[err] is NONE):", "                return {}", "            str hfn = hft[value]", "            dict hfuncs = st[funcs]", "            if NOT hfuncs.contains(hfn):", "                fail(st, hft, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", hfn, \"'\"]))", "                return {}", "            dict hfi = hfuncs.take(hfn)", "            flint hwant = 1", "            if bn == \"reduce\":", "                hwant = 2", "            if len(hfi[params]) != hwant:", "                fail(st, hft, \"ARGCOUNT_ERROR\", cat([str(hwant), \" parameter(s) in '\", hfn, \"'\"]), cat([str(len(hfi[params])), \" parameter(s)\"]))", "                return {}", "            dict hnames = st[fnames]", "            bargs.add({k: \"func_ref\", name: hfn, lua: hnames.take(hfn), t: \"func\", line: hft[line], col: hft[col]})", "            if bn == \"reduce\":", "                expect_tok(st, \"op\", \",\", \"','\")", "                if NOT (st[err] is NONE):", "                    return {}", "                dict hstart = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                bargs.add(hstart)", "            expect_tok(st, \"op\", \")\", \"')'\")", "        else:", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ba1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    bargs.add(ba1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        dict bi = builtin_info(bn)", "        bool bvari = FALSE", "        if bi.contains(\"variadic\"):", "            bvari = bi[variadic]", "        if bvari:", "            if len(bargs) < bi[min] OR len(bargs) > bi[max]:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(bi[min]), \"..\", str(bi[max]), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        else:", "            flint np = bi[n]", "            if len(bargs) != np:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(np), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        flint bai = 0", "        while bai < len(bargs):", "            dict ba2 = bargs[bai]", "            if bvari:", "                if len(bargs) == 1 AND (base_type(ba2[t]) == \"list\" OR ba2[t] == \"any\" OR ba2[t] == \"NONE\"):", "                    bai += 1", "                else:", "                    if NOT builtin_arg_ok(bi[a1], ba2[t]):", "                        fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be flint\"]), ba2[t])", "                        return {}", "                    bai += 1", "            else:", "                str bspec = bi[a1]", "                if bai == 1:", "                    bspec = bi[a2]", "                elif bai == 2:", "                    bspec = bi[a3]", "                if NOT builtin_arg_ok(bspec, ba2[t]):", "                    fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be \", builtin_arg_desc(bspec)]), ba2[t])", "                    return {}", "                bai += 1", "        if bn == \"str\" AND len(bargs) == 1:", "            dict barg0 = bargs[0]", "            if is_model_type(st, barg0[t]):", "                fail(st, barg0, \"TYPE_ERROR\", \"a field or method inside str(...), not a model instance\", barg0[t])", "                return {}", "        e = {k: \"builtin\", name: bn, args: bargs, t: bi[ret], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_template_func(t[value]):", "        pfn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        dict tpl = expect_tok(st, \"template\", \"\", \"template\")", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        ptok = tpl", "    elif ty == \"name\":", "        dict rt = consume_name(st, \"name\")", "        if NOT (st[err] is NONE):", "            return {}", "        str fn = rt[name]", "        t = rt[tok]", "        if is_model_type(st, fn):", "            fail(st, t, \"TYPE_ERROR\", \"a value, not a model name\", cat([\"model '\", fn, \"'\"]))", "            return {}", "        if tk(st)[type] == \"op\" AND tk(st)[value] == \"(\":", "            dict funcs = st[funcs]", "            if NOT funcs.contains(fn):", "                fail(st, t, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", fn, \"'\"]))", "                return {}", "            dict fi = funcs.take(fn)", "            if fi[inferring] AND fi[ret] is NONE:", "                fail(st, t, \"TYPE_ERROR\", \"explicit '->' for recursion\", cat([\"'\", fn, \"' is called while its return type is inferred\"]))", "                return {}", "            expect_tok(st, \"op\", \"(\", \"'('\")", "            list cargs = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ca1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    cargs.add(ca1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            list params = fi[params]", "            if len(cargs) != len(params):", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(params)), \" argument(s) to '\", fn, \"'\"]), cat([str(len(cargs)), \" argument(s)\"]))", "                return {}", "            list ptypes = []", "            flint cai = 0", "            while cai < len(cargs):", "                dict ca2 = cargs[cai]", "                dict pp = params[cai]", "                str pt = pp[type]", "                ptypes.add(pt)", "                if NOT coercion_ok(ca2, pt):", "                    fail(st, {line: ca2[line], col: ca2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cai + 1), \" of '\", fn, \"' to be \", pt]), ca2[t])", "                    return {}", "                cai += 1", "            dict fnames = st[fnames]", "            e = {k: \"call_user\", name: fn, lua: fnames.take(fn), args: cargs, ptypes: ptypes, t: fi[ret], nullable: fi[ret_nullable], line: t[line], col: t[col]}", "            if fi.contains(\"async\") AND fi[\"async\"]:", "                e.add(\"future\", TRUE)", "        else:", "            str vn = fn", "            dict vars = st[vars]", "            bool is_local = vars.contains(vn)", "            dict gv = st[gvars]", "            bool is_global = FALSE", "            bool is_mfield = FALSE", "            dict mctxv = st[model_ctx]", "            if NOT is_local:", "                if gv.contains(vn):", "                    is_global = TRUE", "                elif NOT (mctxv is NONE):", "                    dict ms0 = mctxv[schema]", "                    dict mf0 = ms0[model_fields]", "                    if mf0.contains(vn):", "                        is_mfield = TRUE", "                    else:", "                        fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                        return {}", "                else:", "                    fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                    return {}", "            dict names = st[names]", "            bool nl = FALSE", "            str vt = \"\"", "            if is_mfield:", "                dict ms1 = mctxv[schema]", "                dict mf1 = ms1[model_fields]", "                vt = mf1.take(vn)", "                e = {k: \"model_field\", name: vn, mname: mctxv[model_name], t: vt, line: t[line], col: t[col]}", "            else:", "                if is_local:", "                    vt = vars.take(vn)", "                    dict nd = st[nullable]", "                    if nd.contains(vn):", "                        nl = nd.take(vn)", "                    dict mu = st[maybe_unset]", "                    if mu.contains(vn):", "                        nl = TRUE", "                else:", "                    vt = gv.take(vn)", "                    dict gnl = st[gnullable]", "                    if gnl.contains(vn):", "                        nl = gnl.take(vn)", "                    dict gmu = st[gmaybe]", "                    if gmu.contains(vn):", "                        nl = TRUE", "                e = {k: \"var\", name: vn, lua: names.take(vn), t: vt, nullable: nl, line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"(\":", "        advance(st)", "        e = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "    elif ty == \"op\" AND t[value] == \"[\":", "        advance(st)", "        list items = []", "        if NOT tok_is(tk(st), \"op\", \"]\"):", "            while TRUE:", "                dict it = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                items.add(it)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \"]\", \"']'\")", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"list\", items: items, t: \"list\", line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"\\{\":", "        advance(st)", "        list pairs = []", "        if NOT tok_is(tk(st), \"op\", \"\\}\"):", "            while TRUE:", "                dict dkt = tk(st)", "                str dkey = \"\"", "                str dkty = \"str\"", "                if dkt[type] == \"name\":", "                    advance(st)", "                    dkey = dkt[value]", "                elif dkt[type] == \"string\":", "                    dkey = plain_string_of(st, dkt)", "                    advance(st)", "                    if NOT (st[err] is NONE):", "                        return {}", "                elif dkt[type] == \"number\":", "                    advance(st)", "                    dkey = dkt[value]", "                    dkty = \"flint\"", "                else:", "                    fail(st, dkt, \"TYPE_ERROR\", \"dict key as name, string or number\", describe_tok(dkt))", "                    return {}", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict dval = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                pairs.add({key: dkey, ktype: dkty, value: dval})", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \"\\}\", \"'\\}'\")", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"dict\", pairs: pairs, t: \"dict\", line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"-\":", "        advance(st)", "        dict ua = parse_expr(st, 60)", "        if NOT (st[err] is NONE):", "            return {}", "        if NOT is_numeric(ua[t]):", "            fail(st, t, \"TYPE_ERROR\", \"operand of unary '-' to be flint\", ua[t])", "            return {}", "        e = {k: \"un\", op: \"-\", a: ua, raw: ua[raw], t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"NOT\":", "        advance(st)", "        dict na = parse_expr(st, 25)", "        if NOT (st[err] is NONE):", "            return {}", "        check_condition(st, na, {line: na[line], col: na[col]})", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"un\", op: \"NOT\", a: na, t: \"bool\", line: t[line], col: t[col]}", "    else:", "        fail(st, t, \"SYNTAX_ERROR\", \"expression\", describe_tok(t))", "        return {}", "", "    if NOT (ptok is NONE):", "        list parts = []", "        list raw = ptok[parts]", "        flint pi = 0", "        while pi < len(raw):", "            dict p = raw[pi]", "            if p[kind] == \"text\":", "                parts.add({kind: \"text\", value: p[value]})", "            else:", "                dict sub = template_state(st, p)", "                dict ex = parse_expr(sub, 0)", "                if NOT (sub[err] is NONE):", "                    st.add(\"err\", sub[err])", "                    return {}", "                if NOT (st[err] is NONE):", "                    return {}", "                dict rest = tk(sub)", "                if rest[type] != \"newline\" AND rest[type] != \"eof\":", "                    fail(sub, rest, \"SYNTAX_ERROR\", \"end of expression\", describe_tok(rest))", "                    st.add(\"err\", sub[err])", "                    return {}", "                if is_model_type(st, ex[t]):", "                    fail(st, {line: ex[line], col: ex[col]}, \"TYPE_ERROR\", \"a field or method inside interpolation, not a model instance\", ex[t])", "                    return {}", "                parts.add({kind: \"expr\", expr: ex})", "            pi += 1", "        if pfn == \"\":", "            e = {k: \"str\", parts: parts, t: \"str\", line: t[line], col: t[col]}", "        else:", "            str tt = \"NONE\"", "            if pfn == \"input\":", "                tt = \"str\"", "            e = {k: \"call\", fn: pfn, parts: parts, t: tt, line: t[line], col: t[col]}", "", "    # постфиксы: индексы, срезы, методы", "    bool more = TRUE", "    while more:", "        dict nt = tk(st)", "        if nt[type] == \"op\" AND nt[value] == \"[\":", "            advance(st)", "            str bt = e[t]", "            if base_type(bt) == \"dict\":", "                dict pkt = tk(st)", "                str pkey = \"\"", "                str pkty = \"str\"", "                if pkt[type] == \"name\":", "                    advance(st)", "                    pkey = pkt[value]", "                elif pkt[type] == \"string\":", "                    pkey = plain_string_of(st, pkt)", "                    advance(st)", "                    if NOT (st[err] is NONE):", "                        return {}", "                elif pkt[type] == \"number\":", "                    advance(st)", "                    pkey = pkt[value]", "                    pkty = \"flint\"", "                else:", "                    fail(st, pkt, \"TYPE_ERROR\", \"dict key as name, string or number\", describe_tok(pkt))", "                    return {}", "                expect_tok(st, \"op\", \"]\", \"']'\")", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"dget\", base: e, key: pkey, ktype: pkty, t: \"any\", nullable: TRUE, line: nt[line], col: nt[col]}", "            else:", "                str bbt = base_type(bt)", "                if bbt != \"str\" AND bbt != \"list\" AND bbt != \"froz\" AND bt != \"NONE\" AND bt != \"any\":", "                    fail(st, nt, \"TYPE_ERROR\", \"str, list, froz or dict receiver of an index\", bt)", "                    return {}", "                dict from = {}", "                bool has_from = FALSE", "                if NOT tok_is(tk(st), \"op\", \"..\") AND NOT tok_is(tk(st), \"op\", \"...\"):", "                    from = parse_expr(st, 36)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    has_from = TRUE", "                if tok_is(tk(st), \"op\", \"..\") OR tok_is(tk(st), \"op\", \"...\"):", "                    dict sep_tok = advance(st)", "                    str sep = sep_tok[value]", "                    dict to = {}", "                    bool has_to = FALSE", "                    dict step = {}", "                    bool has_step = FALSE", "                    if sep == \"..\":", "                        if NOT tok_is(tk(st), \"op\", \"]\"):", "                            to = parse_expr(st, 36)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            has_to = TRUE", "                        if tok_is(tk(st), \"op\", \"..\"):", "                            advance(st)", "                            step = parse_expr(st, 36)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            has_step = TRUE", "                    else:", "                        if NOT tok_is(tk(st), \"op\", \"]\"):", "                            step = parse_expr(st, 36)", "                            if NOT (st[err] is NONE):", "                                return {}", "              