 dict cn = consume_name(st, \"variable name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict ctok = cn[tok]", "                str cname = cn[name]", "                dict cw = resolve_write(st, ctok, cname)", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict cop_tok = advance(st)", "                str cop_full = cop_tok[value]", "                str cop = cop_full[..len(cop_full) - 1]", "                dict cexpr = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                str cvt = cw[type]", "                if cvt != \"flint\" OR NOT is_numeric(cexpr[t]):", "                    fail(st, cop_tok, \"TYPE_ERROR\", cat([\"numeric operands of '\", cop_full, \"'\"]), cexpr[t])", "                    return stmts", "                bool cmaybe = FALSE", "                if cw[kind] == \"global\":", "                    dict cgnl = st[gnullable]", "                    dict cgmu = st[gmaybe]", "                    if cgnl.contains(cname):", "                        cmaybe = TRUE", "                    if cgmu.contains(cname):", "                        cmaybe = TRUE", "                    cgnl.remove(cname)", "                else:", "                    dict cnl = st[nullable]", "                    dict cmu = st[maybe_unset]", "                    if cnl.contains(cname):", "                        cmaybe = TRUE", "                    if cmu.contains(cname):", "                        cmaybe = TRUE", "                    cnl.remove(cname)", "                node = {k: \"compound\", name: cname, lua: cw[lua], op: cop, expr: cexpr, nullable: cmaybe, line: ctok[line], col: ctok[col]}", "            else:", "                dict e = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                if e[k] == \"self_init\":", "                    dict sctx = st[model_ctx]", "                    if sctx is NONE OR NOT sctx[in_construct]:", "                        fail(st, e, \"SCOPE_ERROR\", \"self(...) in construct\", \"self(...) outside construct\")", "                        return stmts", "                    if st[block_depth] != sctx[level] OR len(stmts) != 0:", "                        fail(st, e, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"nested or later self(...)\")", "                        return stmts", "                    if sctx[self_seen]:", "                        fail(st, e, \"REDECLARE_ERROR\", \"one self(...) per construct\", \"second self(...)\")", "                        return stmts", "                    list sargs = e[names]", "                    dict ssch = sctx[schema]", "                    dict scons = ssch[ctor]", "                    list sps = []", "                    if NOT (scons is NONE):", "                        sps = scons[params]", "                    flint slast = -1", "                    list sfields = []", "                    flint si = 0", "                    while si < len(sargs):", "                        dict sat = sargs[si]", "                        str san = sat[value]", "                        flint sfound = -1", "                        flint sj = 0", "                        while sj < len(sps):", "                            dict ssp = sps[sj]", "                            if ssp[name] == san:", "                                sfound = sj", "                            sj += 1", "                        if sfound < 0:", "                            fail(st, sat, \"NAME_ERROR\", \"construct parameter in self(...)\", cat([\"unknown '\", san, \"'\"]))", "                            return stmts", "                        if sfound <= slast:", "                            fail(st, sat, \"SYNTAX_ERROR\", \"construct parameters in declaration order\", cat([\"out of order '\", san, \"'\"]))", "                            return stmts", "                        slast = sfound", "                        dict sp = sps[sfound]", "                        add_model_field(st, sctx[schema], sat, san, sp[type], FALSE)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        sfields.add({name: san, type: sp[type], lua: sp[lua], line: sat[line], col: sat[col]})", "                        si += 1", "                    sctx.add(\"self_seen\", TRUE)", "                    sctx.add(\"self_done\", TRUE)", "                    node = {k: \"self_init\", fields: sfields, line: e[line], col: e[col]}", "                elif tok_is(tk(st), \"op\", \"=\"):", "                    str ek = e[k]", "                    if ek == \"field\":", "                        dict fb = e[base]", "                        dict fschema = model_schema(st, e[mname])", "                        str fld = e[name]", "                        dict mctx6 = st[model_ctx]", "                        bool in_con = FALSE", "                        if NOT (mctx6 is NONE) AND mctx6[in_construct] AND fb[k] == \"var\" AND fb[name] == \"self\":", "                            if st[block_depth] == mctx6[level]:", "                                in_con = TRUE", "                        if e[model_field]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"model field '\", fld, \"' is read-only\"]))", "                            return stmts", "                        if e[is_const]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"constant '\", fld, \"' is read-only\"]))", "                            return stmts", "                        dict ftypes6 = fschema[field_types]", "                        if NOT ftypes6.contains(fld):", "                            if NOT in_con OR NOT mctx6[self_done]:", "                                fail(st, e, \"NAME_ERROR\", cat([\"declared field of '\", e[mname], \"'\"]), c