expr: fexpr, type: fexpty, line: eq[line], col: eq[col]}", "                    else:", "                        if ek != \"index\" AND ek != \"dget\":", "                            fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"variable, field or index as assignment target\", ek)", "                            return stmts", "                        if ek == \"index\":", "                            dict seb = e[base]", "                            if seb[t] == \"str\":", "                                fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"mutable index target\", \"str is immutable\")", "                                return stmts", "                        dict eq2 = advance(st)", "                        dict eval2 = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        node = {k: \"setindex\", target: e, expr: eval2, line: eq2[line], col: eq2[col]}", "                else:", "                    node = {k: \"exprstmt\", expr: e, line: e[line], col: e[col]}", "            if NOT decl_block:", "                stmts.add(node)", "                if NOT block_stmt:", "                    dict nx2 = tk(st)", "                    if top:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"eof\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "                    else:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"dedent\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "    if NOT top:", "        if tk(st)[type] == \"dedent\":", "            advance(st)", "        st.add(\"block_depth\", st[block_depth] - 1)", "    return stmts", "", "# Загружает и разбирает один файл. Рекурсивен только сам в себя:", "# вложенные import разбираются этим же вызовом до основного parse_block.", "func process_source(dict st, str path, str src, bool fresh, bool capture_body) -> dict:", "    dict old = {toks: st[toks], pos: st[pos], path: st[path], source: st[source], err: st[err], vars: st[vars], nullable: st[nullable], maybe: st[maybe_unset], fors: st[for_names], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], funcs: st[funcs], names: st[names], fnames: st[fnames], exports: st[exports], models: st[models], vcounter: st[vcounter], fcounter: st[fcounter], block_depth: st[block_depth], loop_depth: st[loop_depth], cond_depth: st[cond_depth], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], model_ctx: st[model_ctx], try_id: st[try_id], try_depth: st[try_depth], try_loop_base: st[try_loop_base], ns_prefix: st[ns_prefix], ns_read_prefix: st[ns_read_prefix]}", "    if fresh:", "        st.add(\"ns_prefix\", \"\")", "        st.add(\"ns_read_prefix\", \"\")", "        st.add(\"vars\", {})", "        st.add(\"nullable\", {})", "        st.add(\"maybe_unset\", {})", "        st.add(\"for_names\", {})", "        st.add(\"gvars\", {})", "        st.add(\"gnullable\", {})", "        st.add(\"gmaybe\", {})", "        st.add(\"funcs\", {})", "        st.add(\"names\", {})", "        st.add(\"fnames\", {})", "        st.add(\"exports\", {})", "        st.add(\"models\", dict_copy(old[models]))", "        st.add(\"vcounter\", old[vcounter])", "        st.add(\"fcounter\", old[fcounter])", "        st.add(\"block_depth\", 0)", "        st.add(\"loop_depth\", 0)", "        st.add(\"cond_depth\", 0)", "        st.add(\"in_func\", FALSE)", "        st.add(\"func_ret\", \"NONE\")", "        st.add(\"func_returns\", [])", "        st.add(\"model_ctx\", NONE)", "        st.add(\"err\", NONE)", "    dict mlx = lex(src, path)", "    if NOT (mlx[err] is NONE):", "        dict e = mlx[err]", "        e.add(\"path\", path)", "        e.add(\"source\", src)", "        record_error(st, e)", "        st.add(\"err\", e)", "        if fresh:", "            for rk1, rv1 in old:", "                st.add(rk1, rv1)", "            st.add(\"err\", e)", "        return {}", "    st.add(\"toks\", mlx[tokens])", "    st.add(\"pos\", 0)", "    st.add(\"path\", path)", "    st.add(\"source\", src)", "    if fresh:", "        add_prelude(st)", "    list stack = st[import_stack]", "    flint si = 0", "    while si < len(stack):", "        if stack[si] == path:", "            fail(st, tk(st), \"REDECLARE_ERROR\", \"import without a cycle\", path)", "            dict ce = st[err]", "            if fresh:", "                for rk2, rv2 in old:", "                    st.add(rk2, rv2)", "                st.add(\"err\", ce)", "            return {}", "        si += 1", "    stack.add(path)", "    st.add(\"import_stack\", stack)", "    flint i = 0", "    flint depth = 0", "    dict bodies = st[import_bodies]", "    while i < len(st[toks]) AND (st[err] is NONE):", "        dict it = st[toks][i]", "        flint nexti = i + 1", "        if it[type] == \"indent\":", "            depth += 1", "        elif it[type] == \"dedent\":", "            depth -= 1", "        elif depth == 0 AND it[type] == \"kw\" AND is_import_kw(it[value]):", "            st.add(\"pos\", i)", "            dict req = parse_import_syntax(st)", "            if NOT (st[err] is NONE):", "                break", "            str full = module_full_path(st, req[kind], req[path], req[tok])", "            dict cache = st[import_cache]", "            dict md = {}", "            bool cached = FALSE", "            if cache.contains(full):", "                md = cache.take(full)", "                cached = TRUE", "            else:", "                if NOT file_exists(full):", "                    fail(st, req[tok], \"FILE_ERROR\", \"module file\", full)", "                    break", "                str msrc = read_file(full)", "                md = process_source(st, full, msrc, TRUE, TRUE)", "                if NOT (st[err] is NONE):", "                    break", "                cache.add(full, md)", "                st.add(\"import_cache\", cache)", "            dict usemd = dict_copy(md)", "            usemd.add(\"bound\", {})", "            dict rtk = req[tok]", "            list reqnames = req[names]", "            str bind_prefix = \"\"", "            if req[kind] == \"import_lib\":", "                bind_prefix = cat([module_short_name(req[path]), \".\"])", "            if len(reqnames) == 0:", "                dict ex0 = usemd[exports]", "                for nm0, nvv0 in ex0:", "                    dict nt0 = {value: nm0, bind_as: cat([bind_prefix, nm0]), line: rtk[line], col: rtk[col]}", "                    bind_export(st, usemd, nt0)", "                    if NOT (st[err] is NONE):", "                        break", "            else:", "                for nt1 in reqnames:", "                    bind_export(st, usemd, nt1)", "                    if NOT (st[err] is NONE):", "                        break", "            if NOT (st[err] is NONE):", "                break", "            if NOT cached:", "                if usemd[vcounter] > st[vcounter]:", "                    st.add(\"vcounter\", usemd[vcounter])", "                if usemd[fcounter] > st[fcounter]:", "                    st.add(\"fcounter\", usemd[fcounter])", "            str bodykey = cat([path, \":\", str(req[start])])", "            if cached:", "                bodies.add(bodykey, [])", "            else:", "                bodies.add(bodykey, usemd[body])", "            st.add(\"import_bodies\", bodies)", "            nexti = st[pos]", "        i = nexti", "    list stack2 = st[import_stack]", "    stack2.del(len(stack2) - 1)", "    st.add(\"import_stack\", stack2)", "    if NOT capture_body:", "        st.add(\"pos\", 0)", "    dict result = {}", "    if capture_body AND (st[err] is NONE):", "        st.add(\"pos\", 0)", "        list body = parse_block(st, TRUE)", "        result = {path: path, body: body, exports: st[exports], vars: st[vars], nullable: st[nullable], funcs: st[funcs], names: st[names], fnames: st[fnames], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], vcounter: st[vcounter], fcounter: st[fcounter], bound: {}}", "    dict finalerr = st[err]", "    if fresh:", "        for rk3, rv3 in old:", "            st.add(rk3, rv3)", "        st.add(\"err\", finalerr)", "    return result", "", "# ---------- кодогенератор ----------", "", "func wrap_flint(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func wrap_str(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_str(\", x, \")\"])", "    return x", "", "func wrap_list(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_list(\", x, \")\"])", "    return x", "", "func wrap_dict(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return x", "", "func wrap_froz(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_froz(\", x, \")\"])", "    return x", "", "func wrap_bool(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_bool(\", x, \")\"])", "    return x", "", "# Приводит значение к базовому типу назначения; параметры типа проверяет рантайм.", "func as_base(str x, str target) -> str:", "    str b = base_type(target)", "    if b == \"flint\":", "        return cat([\"krt.as_flint(\", x, \")\"])", "    if b == \"str\":", "        return cat([\"krt.as_str(\", x, \")\"])", "    if b == \"bool\":", "        return cat([\"krt.as_bool(\", x, \")\"])", "    if b == \"list\":", "        return cat([\"krt.as_list(\", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.as_froz(\", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return cat([\"krt.as_model(\", x, lua_str(target), \")\"])", "", "# Присоединяет спецификацию параметризованного типа к коллекции.", "func typed_wrap(str x, str target) -> str:", "    if NOT is_typed_spec(target):", "        return x", "    str b = base_type(target)", "    if b == \"list\":", "        return cat([\"krt.typed_list(\", lua_str(target), \", \", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.typed_froz(\", lua_str(target), \", \", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.typed_dict(\", lua_str(target), \", \", x, \")\"])", "    return x", "", "func coerce_to(str x, str ety, str target) -> str:", "    if ety == \"str\" AND target == \"flint\":", "        return cat([\"krt.to_flint(\", x, \")\"])", "    return x", "", "func checked(str x, str ety, bool nullable, str target) -> str:", "    x = coerce_to(x, ety, target)", "    if ety == \"any\" AND NOT nullable:", "        return as_base(x, target)", "    return x", "", "func wrap_to(str x, str ety, bool nullable, str target) -> str:", "    x = coerce_to(x, ety, target)", "    if ety == \"NONE\" OR ety == \"any\" OR nullable:", "        return as_base(x, target)", "    return x", "", "func ordered_x(str x, dict e, dict other) -> str:", "    if e[t] == \"NONE\" OR e_nullable(e):", "        str ty = e[t]", "        if ty == \"NONE\":", "            ty = other[t]", "        if ty == \"str\":", "            return cat([\"krt.as_str(\", x, \")\"])", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func emit_line(dict st, str s):", "    if NOT (st[cur_pos] is NONE):", "        dict cp = st[cur_pos]", "        if len(cp) > 0:", "            list lm = st[line_map]", "            lm.add({gen: len(st[out]) + 1, line: cp[line], col: cp[col]})", "    list o = st[out]", "    o.add(cat([spaces(st[indent] * 4), s]))", "", "func stmt_pos(dict s) -> dict:", "    str sk = s[k]", "    if sk == \"panic\":", "        return {line: s[line], col: s[col]}", "    if sk == \"decl\" OR sk == \"assign\" OR sk == \"compound\" OR sk == \"exprstmt\" OR sk == \"return\":", "        if s.contains(\"expr\"):", "            dict e = s[expr]", "            return {line: e[line], col: e[col]}", "    if sk == \"if\":", "        list brs = s[branches]", "        dict b0 = brs[0]", "        dict c0 = b0[cond]", "        return {line: c0[line], col: c0[col]}", "    if sk == \"while\":", "        dict wc = s[cond]", "        return {line: wc[line], col: wc[col]}", "    if sk == \"for\":", "        if s.contains(\"from\"):", "            dict fe = s[from]", "            return {line: fe[line], col: fe[col]}", "        dict te = s[to]", "        return {line: te[line], col: te[col]}", "    if sk == \"for_in\":", "        dict cc = s[coll]", "        return {line: cc[line], col: cc[col]}", "    return {line: s[line], col: s[col]}", "", "# Future statically has the result type; the wait is inserted at the first use.", "# Assignment to a variable is not a use: emit_future_call keeps the future in", "# the variable, and emit_await_var waits when that variable is read.", "func register_future(dict st, str lua, str ety, bool nullable, str target):", "    dict fu = st[futures]", "    fu.add(lua, TRUE)", "    dict fts = st[future_types]", "    fts.add(lua, {ety: ety, nullable: nullable, target: target})", "", "func emit_await_var(dict st, str lua) -> str:", "    dict fu = st[futures]", "    if NOT fu.contains(lua):", "        return lua", "    str x = cat([\"krt.future_await(\", lua, \")\"])", "    dict fts = st[future_types]", "    if fts.contains(lua):", "        dict fi = fts.take(lua)", "        fts.add(lua, fi)", "        x = checked(x, fi[\"ety\"], fi[\"nullable\"], fi[\"target\"])", "        if fi[\"ety\"] != \"NONE\":", "            x = typed_wrap(x, fi[\"target\"])", "    return x", "", "# Выражение -> текст Lua. Рекурсивна только сама в себя.", "func emit_expr(dict st, dict e) -> str:", "    str k = e[k]", "", "    if k == \"num\":", "        return cat([\"(\", str(e[value]), \")\"])", "    if k == \"bool\":", "        if e[value]:", "            return \"true\"", "        return \"false\"", "    if k == \"none\":", "        return \"krt.NONE\"", "    if k == \"const\":", "        return cat([\"krt.\", e[name]])", "    if k == \"var\":", "        return emit_await_var(st, e[lua])", "", "    if k == \"model_field\":", "        return cat([\"krt.model_get(self, \", lua_str(e[name]), \")\"])", "    if k == \"field\":", "        return cat([\"krt.model_get(\", emit_expr(st, e[base]), \", \", lua_str(e[name]), \")\"])", "    if k == \"model_new\":", "        list mna = e[args]", "        list mnp = [lua_str(e[mname])]", "        flint mni = 0", "        list mnpt = e[ptypes]", "        while mni < len(mna):", "            dict mnarg = mna[mni]", "            mnp.add(coerce_to(emit_expr(st, mnarg), mnarg[t], mnpt[mni]))", "            mni += 1", "        return cat([\"krt.model_new(\", mnp.join(\", \"), \")\"])", "    if k == \"model_init\":", "        list mia = e[args]", "        list mip = []", "        for mia0 in mia:", "            dict mian = mia0", "            dict miax = mian[expr]", "            mip.add(cat([\"[\", lua_str(mian[name]), \"] = \", coerce_to(emit_expr(st, miax), miax[t], mian[type])]))", "        return cat([\"krt.model_init(\", lua_str(e[mname]), \", \\{\", mip.join(\", \"), \"\\})\"])", "    if k == \"model_method\":", "        list mma2 = e[args]", "        list mmp2 = [emit_expr(st, e[base]), lua_str(e[name])]", "        list mmpt2 = e[ptypes]", "        flint mmi2 = 0", "        while mmi2 < len(mma2):", "            dict mmarg = mma2[mmi2]", "            str mmtgt = mmpt2[mmi2]", "            mmp2.add(wrap_to(emit_expr(st, mmarg), mmarg[t], e_nullable(mmarg), mmtgt))", "            mmi2 += 1", "        return cat([\"krt.model_call(\", mmp2.join(\", \"), \")\"])", "    if k == \"self_init\":", "        return \"krt.NONE\"", "", "    if k == \"func_ref\":", "        return e[lua]", "", "    if k == \"str\" OR k == \"call\":", "        list parts = e[parts]", "        list pieces = []", "        for p0 in parts:", "            dict p = p0", "            if p[kind] == \"text\":", "                pieces.add(lua_str(p[value]))", "            else:", "                dict pe = p[expr]", "                str conv = \"krt.tostr\"", "                dict range_names = st[range_floats]", "                if NOT (range_names is NONE) AND pe[k] == \"var\" AND range_names.contains(pe[lua]):", "                    conv = \"krt.tostr_range_flint\"", "                pieces.add(cat([conv, \"(\", emit_expr(st, pe), \")\"]))", "        str body = \"\\\"\\\"\"", "        if len(pieces) == 1:", "            body = pieces[0]", "        elif len(pieces) > 1:", "            body = cat([\"(\", pieces.join(\" .. \"), \")\"])", "        if k == \"str\":", "            return body", "        str f = e[fn]", "        if f == \"show\":", "            return cat([\"krt.show(\", body, \")\"])", "        if f == \"show_err\":", "            return cat([\"krt.show_err(\", body, \")\"])", "        return cat([\"krt.input(\", body, \")\"])", "", "    if k == \"builtin\":", "        str bn = e[name]", "        list ba = e[args]", "        if bn == \"args\":", "            return \"krt.args()\"", "        if bn == \"time_ms\":", "            return \"krt.time_ms()\"", "        if bn == \"is_tty\":", "            return \"krt.is_tty()\"", "        dict a0 = ba[0]", "        if bn == \"timer\":", "            dict ta1 = ba[1]", "            return cat([\"krt.timer(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, ta1), \")\"])", "        if bn == \"len\":", "            return cat([\"krt.len(\", emit_expr(st, a0), \")\"])", "        if bn == \"type\":", "            return cat([\"krt.typeof(\", emit_expr(st, a0), \")\"])", "        if bn == \"str\":", "            return cat([\"krt.tostr(\", emit_expr(st, a0), \")\"])", "        if bn == \"flint\":", "            return cat([\"krt.to_flint(\", emit_expr(st, a0), \")\"])", "        if bn == \"up\":", "            return cat([\"krt.str_up(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"low\":", "            return cat([\"krt.str_low(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"title\":", "            return cat([\"krt.str_title(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"abs\":", "            return cat([\"krt.num_abs(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"round\":", "            return cat([\"krt.num_round(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"floor\":", "            return cat([\"krt.num_floor(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"ceil\":", "            return cat([\"krt.num_ceil(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sqrt\":", "            return cat([\"krt.num_sqrt(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"factorial\":", "            return cat([\"krt.num_factorial(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"fib\":", "            return cat([\"krt.num_fib(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"rand_num\":", "            return cat([\"krt.rand_num(\", emit_expr(st, a0), \")\"])", "        if bn == \"rand_choice\":", "            return cat([\"krt.rand_choice(\", emit_expr(st, a0), \")\"])", "        if bn == \"min\" OR bn == \"max\":", "            list mvals = []", "            for mn0 in ba:", "                dict mnode = mn0", "                if base_type(mnode[t]) == \"list\":", "                    mvals.add(wrap_list(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "                else:", "                    mvals.add(wrap_flint(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "            return cat([\"krt.num_\", bn, \"(\", mvals.join(\", \"), \")\"])", "        if bn == \"sum\":", "            return cat([\"krt.coll_sum(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"avg\":", "            return cat([\"krt.coll_avg(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"keys\":", "            return cat([\"krt.coll_keys(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"values\":", "            return cat([\"krt.coll_values(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"upk\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_upk(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_upk(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sort\":", "            return cat([\"krt.coll_sort(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"reverse\":", "            return cat([\"krt.coll_reverse(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"clear\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_clear(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_clear(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"map\" OR bn == \"filter\":", "            dict hf = ba[1]", "            return cat([\"krt.coll_\", bn, \"(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, hf), \")\"])", "        if bn == \"reduce\":", "            dict rf = ba[1]", "            dict rs = ba[2]", "            return cat([\"krt.coll_reduce(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, rf), \", \", emit_expr(st, rs), \")\"])", "        if bn == \"system\":", "            return cat([\"krt.system(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"assert\":", "            dict amsg = ba[1]", "            return cat([\"krt.do_assert_strict(\", emit_expr(st, a0), \", \", wrap_str(emit_expr(st, amsg), amsg[t], e_nullable(amsg)), \")\"])", "        if bn == \"expect\":", "            return cat([\"krt.expect_new(\", emit_expr(st, a0), \")\"])", "        if bn == \"read_file\":", "            return cat([\"krt.read_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"write_file\":", "            dict a1 = ba[1]", "            return cat([\"krt.write_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", wrap_str(emit_expr(st, a1), a1[t], e_nullable(a1)), \")\"])", "        if bn == \"file_exists\":", "            return cat([\"krt.file_exists(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"copy_file\":", "            dict cfa1 = ba[1]", "            return cat([\"krt.copy_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", wrap_str(emit_expr(st, cfa1), cfa1[t], e_nullable(cfa1)), \")\"])", "        if bn == \"remove_file\":", "            return cat([\"krt.remove_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"json_parse\":", "            return cat([\"krt.json_parse(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"json_stringify\":", "            return cat([\"krt.json_stringify(\", emit_expr(st, a0), \")\"])", "        if bn == \"exit\":", "            return cat([\"krt.exit(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"raise\":", "            dict fmsg = ba[1]", "            return cat([\"krt.fail(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", wrap_str(emit_expr(st, fmsg), fmsg[t], e_nullable(fmsg)), \")\"])", "        return \"krt.NONE\"", "", "    if k == \"call_user\":", "        list car = e[args]", "        list cp = []", "        list cpt = e[ptypes]", "        flint ci = 0", "        while ci < len(car):", "            dict cnode = car[ci]", "            str ctgt = cpt[ci]", "            str cx = emit_expr(st, cnode)", "            cp.add(wrap_to(cx, cnode[t], e_nullable(cnode), ctgt))", "            ci += 1", "        str ccall = cat([e[lua], \"(\", cp.join(\", \"), \")\"])", "        if e.contains(\"future\"):", "            return cat([\"krt.future_await(\", ccall, \")\"])", "        return ccall", "", "    if k == \"list\":", "        list its = e[items]", "        list ip = []", "        for it0 in its:", "            dict itn = it0", "            ip.add(emit_expr(st, itn))", "        return cat([\"krt.list(\\{\", ip.join(\", \"), \"\\})\"])", "", "    if k == \"dict\":", "        list prs = e[pairs]", "        str dx = \"krt.dict()\"", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            str rawk = str(pd[key])", "            str dk = \"\"", "            if pd[ktype] == \"flint\":", "                dk = rawk", "            else:", "                dk = lua_str(rawk)", "            dx = cat([\"krt.dict_set(\", dx, \", \", dk, \", \", emit_expr(st, pv), \")\"])", "        return dx", "", "    if k == \"dget\":", "        dict db = e[base]", "        str rawgk = str(e[key])", "        str gk = \"\"", "        if e[ktype] == \"flint\":", "            gk = rawgk", "        else:", "            gk = lua_str(rawgk)", "        return cat([\"krt.dict_get(\", wrap_dict(emit_expr(st, db), db[t], e_nullable(db)), \", \", gk, \")\"])", "", "    if k == \"index\":", "        dict ib = e[base]", "        dict ii = e[index]", "        str ix = wrap_flint(emit_expr(st, ii), ii[t], e_nullable(ii))", "        str ibb = base_type(ib[t])", "        if ibb == \"list\":", "            return cat([\"krt.list_index(\", wrap_list(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ibb == \"froz\":", "            return cat([\"krt.list_index(\", wrap_froz(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ib[t] == \"any\":", "            return cat([\"krt.index(\", emit_expr(st, ib), \", \", ix, \")\"])", "        return cat([\"krt.str_index(\", wrap_str(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "", "    if k == \"slice\":", "        dict sb = e[base]", "        str sx = emit_expr(st, sb)", "        str sfn = \"str_slice\"", "        str recv = wrap_str(sx, sb[t], e_nullable(sb))", "        str sbb = base_type(sb[t])", "        if sbb == \"list\":", "            sfn = \"list_slice\"", "            recv = wrap_list(sx, sb[t], e_nullable(sb))", "        elif sbb == \"froz\":", "            sfn = \"list_slice\"", "            recv = wrap_froz(sx, sb[t], e_nullable(sb))", "        elif sb[t] == \"any\":", "            sfn = \"slice\"", "            recv = sx", "        list sp = [recv]", "        if e[from] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict fr = e[from]", "            sp.add(wrap_flint(emit_expr(st, fr), fr[t], e_nullable(fr)))", "        if e[to] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict tto = e[to]", "            sp.add(wrap_flint(emit_expr(st, tto), tto[t], e_nullable(tto)))", "        if NOT (e[step] is NONE):", "            dict stp = e[step]", "            sp.add(wrap_flint(emit_expr(st, stp), stp[t], e_nullable(stp)))", "        return cat([\"krt.\", sfn, \"(\", sp.join(\", \"), \")\"])", "", "    if k == \"method\":", "        dict mb = e[base]", "        str mx = emit_expr(st, mb)", "        str mrecv = wrap_str(mx, mb[t], e_nullable(mb))", "        str mbb = base_type(mb[t])", "        if mbb == \"list\":", "            mrecv = wrap_list(mx, mb[t], e_nullable(mb))", "        elif mbb == \"froz\":", "            mrecv = wrap_froz(mx, mb[t], e_nullable(mb))", "        elif mbb == \"dict\":", "            mrecv = wrap_dict(mx, mb[t], e_nullable(mb))", "        list mar = e[args]", "        list mp = [mrecv]", "        flint mi = 0", "        while mi < len(mar):", "            dict ma = mar[mi]", "            str mspec = e[a1]", "            if mi == 1:", "                mspec = e[a2]", "            str mxx = emit_expr(st, ma)", "            if mspec == \"str\":", "                mxx = wrap_str(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"flint\":", "                mxx = wrap_flint(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"dict\":", "                mxx = wrap_dict(mxx, ma[t], e_nullable(ma))", "            mp.add(mxx)", "            mi += 1", "        return cat([\"krt.\", e[rt], \"(\", mp.join(\", \"), \")\"])", "", "    if k == \"un\":", "        dict ua = e[a]", "        if e[op] == \"-\":", "            return cat([\"(-(\", wrap_flint(emit_expr(st, ua), ua[t], e_nullable(ua)), \"))\"])", "        return cat([\"(not krt.truthy_strict(\", emit_expr(st, ua), \"))\"])", "", "    if k == \"is\":", "        dict ia = e[a]", "        str ix2 = emit_expr(st, ia)", "        str ty2 = e[typename]", "        if ty2 == \"flint\":", "            return cat([\"(type(\", ix2, \") == \\\"number\\\")\"])", "        if ty2 == \"str\":", "            return cat([\"(type(\", ix2, \") == \\\"string\\\")\"])", "        if ty2 == \"bool\":", "            return cat([\"(type(\", ix2, \") == \\\"boolean\\\")\"])", "        str tyb = base_type(ty2)", "        if tyb == \"list\":", "            return cat([\"krt.is_list(\", ix2, \")\"])", "        if tyb == \"froz\":", "            return cat([\"krt.is_froz(\", ix2, \")\"])", "        if tyb == \"dict\":", "            return cat([\"krt.is_dict(\", ix2, \")\"])", "        if is_model_type(st, ty2):", "            return cat([\"krt.is_model(\", ix2, \", \", lua_str(ty2), \")\"])", "        return cat([\"(\", ix2, \" == krt.NONE or \", ix2, \" == nil)\"])", "", "    if k == \"range\":", "        dict rex = e[from]", "        dict rey = e[to]", "        dict rez = e[step]", "        return cat([\"krt.range_new(\", wrap_flint(emit_expr(st, rex), rex[t], e_nullable(rex)), \", \", wrap_flint(emit_expr(st, rey), rey[t], e_nullable(rey)), \", \", wrap_flint(emit_expr(st, rez), rez[t], e_nullable(rez)), \", \", lua_str(e[kind]), \")\"])", "", "    if k == \"in\":", "        dict iax = e[a]", "        dict ibx = e[b]", "        str ixf = emit_expr(st, iax)", "        str iyb = emit_expr(st, ibx)", "        if ibx[t] == \"range\":", "            return cat([\"krt.in_range(\", wrap_flint(ixf, iax[t], e_nullable(iax)), \", \", iyb, \")\"])", "        str ibt = base_type(ibx[t])", "        if ibt == \"list\" OR ibt == \"froz\":", "            return cat([\"krt.in_list(\", ixf, \", \", wrap_list(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        if ibt == \"dict\":", "            return cat([\"krt.in_dict_keys(\", wrap_str(ixf, iax[t], e_nullable(iax)), \", \", wrap_dict(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        if ibx[t] == \"str\":", "            return cat([\"krt.in_str(\", wrap_str(ixf, iax[t], e_nullable(iax)), \", \", wrap_str(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        return cat([\"krt.in_list(\", ixf, \", \", iyb, \")\"])", "", "    if k == \"bin\":", "        str op = e[op]", "        dict bna = e[a]", "        dict bnb = e[b]", "        str xa = emit_expr(st, bna)", "        str xb = emit_expr(st, bnb)", "        if op == \"+\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" + \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"-\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" - \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"*\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" * \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"/\":", "            return cat([\"krt.div(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"//\":", "            return cat([\"krt.idiv(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"%\":", "            return cat([\"krt.mod(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"**\":", "            return cat([\"krt.pow(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"==\":", "            return cat([\"(\", xa, \" == \", xb, \")\"])", "        if op == \"!=\":", "            return cat([\"(\", xa, \" ~= \", xb, \")\"])", "        if op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\":", "            if bna[t] == \"any\" OR bnb[t] == \"any\":", "                str cfn = \"lt\"", "                if op == \"<=\":", "                    cfn = \"le\"", "                elif op == \">\":", "                    cfn = \"gt\"", "                elif op == \">=\":", "                    cfn = \"ge\"", "                return cat([\"krt.\", cfn, \"(\", xa, \", \", xb, \")\"])", "            return cat([\"(\", ordered_x(xa, bna, bnb), \" \", op, \" \", ordered_x(xb, bnb, bna), \")\"])", "        if op == \"AND\":", "            return cat([\"(krt.truthy_strict(\", xa, \") and krt.truthy_strict(\", xb, \"))\"])", "        if op == \"OR\":", "            return cat([\"(krt.truthy_strict(\", xa, \") or krt.truthy_strict(\", xb, \"))\"])", "        return \"krt.NONE\"", "", "    if k == \"chain\":", "        list cops = e[ops]", "        list coper = e[operands]", "        list clines = []", "        list cconds = []", "        dict cprev_node = coper[0]", "        str cprev = emit_expr(st, cprev_node)", "        flint cj = 0", "        while cj < len(cops):", "            dict co = cops[cj]", "            dict crhs_node = coper[cj + 1]", "            str crhs = \"\"", "            if cj < len(cops) - 1:", "                crhs = cat([\"__t\", str(cj + 1)])", "                clines.add(cat([\"local \", crhs, \" = \", emit_expr(st, crhs_node)]))", "            else:", "                crhs = emit_expr(st, crhs_node)", "            str cl = cprev", "            str cr = crhs", "            str cop2 = co[op]", "            if cop2 == \"==\":", "                cconds.add(cat([\"(\", cl, \" == \", cr, \")\"]))", "            elif cop2 == \"!=\":", "                cconds.add(cat([\"(\", cl, \" ~= \", cr, \")\"]))", "            elif cprev_node[t] == \"any\" OR crhs_node[t] == \"any\":", "                str cfn2 = \"lt\"", "                if cop2 == \"<=\":", "                    cfn2 = \"le\"", "                elif cop2 == \">\":", "                    cfn2 = \"gt\"", "                elif cop2 == \">=\":", "                    cfn2 = \"ge\"", "                cconds.add(cat([\"krt.\", cfn2, \"(\", cl, \", \", cr, \")\"]))", "            else:", "                if cprev_node[t] == \"NONE\" OR e_nullable(cprev_node):", "                    if cprev_node[t] == \"str\":", "                        cl = cat([\"krt.as_str(\", cl, \")\"])", "                    else:", "                        cl = cat([\"krt.as_flint(\", cl, \")\"])", "                if crhs_node[t] == \"NONE\" OR e_nullable(crhs_node):", "                    if crhs_node[t] == \"str\":", "                        cr = cat([\"krt.as_str(\", cr, \")\"])", "                    else:", "                        cr = cat([\"krt.as_flint(\", cr, \")\"])", "                cconds.add(cat([\"(\", cl, \" \", cop2, \" \", cr, \")\"]))", "            cprev = crhs", "            cprev_node = crhs_node", "            cj += 1", "        str cpre = \"\"", "        if len(clines) > 0:", "            cpre = cat([clines.join(\"; \"), \"; \"])", "        return cat([\"(function() \", cpre, \"return \", cconds.join(\" and \"), \" end)()\"])", "", "    return \"krt.NONE\"", "", "# Присваивание future не является его первым использованием: снимаем метку,", "# чтобы обычный вызов не вставил ожидание, и сохраняем future в переменной.", "func emit_future_call(dict st, dict e) -> str:", "    dict ce = dict_copy(e)", "    ce.remove(\"future\")", "    return emit_expr(st, ce)", "", "# Объявления поднимаются в начало своей функции (D11, D43).", "func collect_walk(list stmts, list out) -> list:", "    for s0 in stmts:", "        dict s = s0", "        str sk = s[k]", "        if sk == \"decl\":", "            out.add(s[lua])", "        elif sk == \"import\" OR sk == \"namespace\":", "            collect_walk(s[body], out)", "        elif sk == \"if\":", "            list brs = s[branches]", "            for b0 in brs:", "                dict b = b0", "                collect_walk(b[body], out)", "            if s.contains(\"else_body\"):", "                collect_walk(s[else_body], out)", "        elif sk == \"while\" OR sk == \"for\" OR sk == \"for_in\":", "            collect_walk(s[body], out)", "        elif sk == \"try\":", "            collect_walk(s[body], out)", "            for h0 in s[triggers]:", "                dict h = h0", "                collect_walk(h[body], out)", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                collect_walk(ha[body], out)", "            collect_walk(s[\"finally\"], out)", "    return out", "", "func collect_scope(list stmts) -> list:", "    list out = []", "    collect_walk(stmts, out)", "    return out", "", "func emit_hoist(dict st, list names):", "    if len(names) == 0:", "        return:", "    list lua = []", "    list nones = []", "    for n0 in names:", "        str n = n0", "        lua.add(n)", "        nones.add(\"krt.NONE\")", "    emit_line(st, cat([\"local \", lua.join(\", \"), \" = \", nones.join(\", \")]))", "", "func lua_str_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = \", lua_str(d.take(k))]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func lua_true_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = true\"]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func cat_lists(list a, list b) -> list:", "    list out = []", "    for x in a:", "        out.add(x)", "    for y in b:", "        out.add(y)", "    return out", "", "func lua_str_list(list xs) -> str:", "    list parts = []", "    for x in xs:", "        parts.add(lua_str(x))", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "# Стейтменты -> строки Lua. Рекурсивна только сама в себя.", "func emit_stmts(dict st, list stmts) -> str:", "    flint i = 0", "    while i < len(stmts):", "        dict s = stmts[i]", "        dict saved = st[cur_pos]", "        st.add(\"cur_pos\", stmt_pos(s))", "        str sk = s[k]", "        bool wrap_ret = FALSE", "        if sk == \"import\" OR sk == \"namespace\":", "            emit_stmts(st, s[body])", "        if sk == \"return\" AND i < len(stmts) - 1:", "            wrap_ret = TRUE", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "        if sk == \"model\":", "            dict msc = s[schema]", "            str mn2 = s[name]", "            dict msc_mf = msc[model_fields]", "            dict msc_ft = msc[field_types]", "            dict msc_cs = msc[consts]", "            dict msc_if = msc[init_fields]", "            dict msc_pt = msc[param_types]", "            list msc_ord = msc[order]", "            list msc_fo = msc[field_order]", "            list msc_pl = msc[params]", "            list msc_all = msc_fo", "            emit_line(st, cat([\"krt.model_define(\", lua_str(mn2), \", \", lua_str_map_keys(msc_mf, msc_ord), \", \", lua_str_map_keys(msc_ft, msc_all), \", \", lua_true_map_keys(msc_cs, msc_all), \", \", lua_true_map_keys(msc_if, msc_fo), \", \", lua_str_list(msc_pl), \", \", lua_str_map_keys(msc_pt, msc_pl), \")\"]))", "            list mflds = s[fields]", "            for mf0 in mflds:", "                dict mfn2 = mf0", "                dict mfe = mfn2[expr]", "                str mfx = coerce_to(emit_expr(st, mfe), mfe[t], mfn2[type])", "                emit_line(st, cat([\"krt.model_set_value(\", lua_str(mn2), \", \", lua_str(mfn2[name]), \", \", mfx, \")\"]))", "            dict mcons2 = msc[ctor]", "            list mcps = mcons2[params]", "            list mcpl = [\"self\"]", "            for mcp0 in mcps:", "                dict mcp = mcp0", "                mcpl.add(mcp[lua])", "            emit_line(st, cat([\"krt.model_construct(\", lua_str(mn2), \", function(\", mcpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            str msv = st[current_ret]", "            st.add(\"current_ret\", \"NONE\")", "            list mcbody = mcons2[body]", "            emit_hoist(st, collect_scope(mcbody))", "            emit_stmts(st, mcbody)", "            st.add(\"current_ret\", msv)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            list mmorder = msc[method_order]", "            for mmn2 in mmorder:", "                dict msmeth6 = msc[methods]", "                dict mmi2 = msmeth6.take(mmn2)", "                list mmps = [ \"self\" ]", "                list mmpl = mmi2[params]", "                for mmp0 in mmpl:", "                    dict mmp = mmp0", "                    mmps.add(mmp[lua])", "                emit_line(st, cat([\"krt.model_method(\", lua_str(mn2), \", \", lua_str(mmn2), \", function(\", mmps.join(\", \"), \")\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str msv2 = st[current_ret]", "                st.add(\"current_ret\", mmi2[ret])", "                list mmbody = mmi2[body]", "                emit_hoist(st, collect_scope(mmbody))", "                emit_stmts(st, mmbody)", "                st.add(\"current_ret\", msv2)", "                bool mmend = FALSE", "                if len(mmbody) > 0:", "                    dict mmlast = mmbody[len(mmbody) - 1]", "                    if mmlast[k] == \"return\":", "                        mmend = TRUE", "                if NOT mmend:", "                    emit_line(st, \"return krt.NONE\")", "                st.add(\"indent\", st[indent] - 1)", "                emit_line(st, \"end)\")", "        elif sk == \"self_init\":", "            list sfl = s[fields]", "            for sf0 in sfl:", "                dict sf = sf0", "                emit_line(st, cat([\"krt.model_create_field(self, \", lua_str(sf[name]), \", \", sf[lua], \", \", \"false\", \", \", lua_str(sf[type]), \")\"]))", "        elif sk == \"field_create\":", "            dict fce = s[expr]", "            str fcx = checked(emit_expr(st, fce), fce[t], e_nullable(fce), s[type])", "            str fcb = emit_expr(st, s[base])", "            str fcc = \"false\"", "            if is_const_name(s[name]):", "                fcc = \"true\"", "            emit_line(st, cat([\"krt.model_create_field(\", fcb, \", \", lua_str(s[name]), \", \", fcx, \", \", fcc, \", \", lua_str(s[type]), \")\"]))", "        elif sk == \"field_assign\":", "            dict fae = s[expr]", "            str fax = checked(emit_expr(st, fae), fae[t], e_nullable(fae), s[type])", "            emit_line(st, cat([\"krt.model_set(\", emit_expr(st, s[base]), \", \", lua_str(s[name]), \", \", fax, \")\"]))", "        elif sk == \"decl\":", "            dict de = s[expr]", "            bool dhold = de.contains(\"future\")", "            str dx = \"\"", "            if dhold:", "                dx = emit_future_call(st, de)", "            else:", "                dx = emit_expr(st, de)", "            if dhold:", "                register_future(st, s[lua], de[t], e_nullable(de), s[type])", "            else:", "                dx = checked(dx, de[t], e_nullable(de), s[type])", "                if de[t] != \"NONE\":", "                    dx = typed_wrap(dx, s[type])", "            emit_line(st, cat([s[lua], \" = \", dx]))", "        elif sk == \"assign\":", "            dict ae = s[expr]", "            bool ahold = ae.contains(\"future\")", "            str ax = \"\"", "            if ahold:", "                ax = emit_future_call(st, ae)", "            else:", "                ax = emit_expr(st, ae)", "            if ahold:", "                register_future(st, s[lua], ae[t], e_nullable(ae), s[type])", "            else:", "                ax = checked(ax, ae[t], e_nullable(ae), s[type])", "                if ae[t] != \"NONE\":", "                    ax = typed_wrap(ax, s[type])", "            emit_line(st, cat([s[lua], \" = \", ax]))", "        elif sk == \"compound\":", "            dict ce = s[expr]", "            str lhs = wrap_flint(emit_await_var(st, s[lua]), \"flint\", s[nullable])", "            str rhs = wrap_flint(emit_expr(st, ce), ce[t], e_nullable(ce))", "            str cop = s[op]", "            str ex = \"\"", "            if cop == \"+\":", "                ex = cat([\"(\", lhs, \" + \", rhs, \")\"])", "            elif cop == \"-\":", "                ex = cat([\"(\", lhs, \" - \", rhs, \")\"])", "            elif cop == \"*\":", "                ex = cat([\"(\", lhs, \" * \", rhs, \")\"])", "            elif cop == \"/\":", "                ex = cat([\"krt.div(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"//\":", "                ex = cat([\"krt.idiv(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"%\":", "                ex = cat([\"krt.mod(\", lhs, \", \", rhs, \")\"])", "            else:", "                ex = cat([\"krt.pow(\", lhs, \", \", rhs, \")\"])", "            emit_line(st, cat([s[lua], \" = \", ex]))", "        elif sk == \"setindex\":", "            dict tg = s[target]", "            dict tv = s[expr]", "            str tvx = emit_expr(st, tv)", "            if tg[k] == \"dget\":", "                dict tb = tg[base]", "                str tdx = wrap_dict(emit_expr(st, tb), tb[t], e_nullable(tb))", "                str rawtk = str(tg[key])", "                str tdk = \"\"", "                if tg[ktype] == \"flint\":", "                    tdk = rawtk", "                else:", "                    tdk = lua_str(rawtk)", "                emit_line(st, cat([\"krt.dict_set(\", tdx, \", \", tdk, \", \", tvx, \")\"]))", "            else:", "                dict tib = tg[base]", "                dict tii = tg[index]", "                str tbx = emit_expr(st, tib)", "                str tix = wrap_flint(emit_expr(st, tii), tii[t], e_nullable(tii))", "                str tibb = base_type(tib[t])", "                if tibb == \"list\" OR tibb == \"froz\":", "                    str tbx2 = \"\"", "                    if tibb == \"froz\":", "                        tbx2 = wrap_froz(tbx, tib[t], e_nullable(tib))", "                    else:", "                        tbx2 = wrap_list(tbx, tib[t], e_nullable(tib))", "                    emit_line(st, cat([\"krt.list_replace(\", tbx2, \", \", tix, \", \", tvx, \")\"]))", "                else:", "                    emit_line(st, cat([\"krt.index_set(\", tbx, \", \", tix, \", \", tvx, \")\"]))", "        elif sk == \"panic\":", "            emit_line(st, cat([\"krt.fail(\", lua_str(s[cat]), \", \", lua_str(s[msg]), \")\"]))", "        elif sk == \"exprstmt\":", "            emit_line(st, emit_expr(st, s[expr]))", "        elif sk == \"if\":", "            list brs = s[branches]", "            flint bi = 0", "            while bi < len(brs):", "                dict br = brs[bi]", "                dict bc = br[cond]", "                str kw = \"elseif\"", "                if bi == 0:", "                    kw = \"if\"", "                emit_line(st, cat([kw, \" krt.truthy_strict(\", emit_expr(st, bc), \") then\"]))", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, br[body])", "                st.add(\"indent\", st[indent] - 1)", "                bi += 1", "            if s.contains(\"else_body\"):", "                emit_line(st, \"else\")", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, s[else_body])", "                st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"try\":", "            st.add(\"try_id\", st[try_id] + 1)", "            str tid = str(st[try_id])", "            str tnorm = cat([\"__try_normal_\", tid])", "            str tok2 = cat([\"__try_ok_\", tid])", "            str tval2 = cat([\"__try_val_\", tid])", "            str terr2 = cat([\"__try_err_\", tid])", "            str thok = cat([\"__try_hok_\", tid])", "            str hval2 = cat([\"__try_hval_\", tid])", "            str thandled = cat([\"__try_handled_\", tid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local \", tnorm, \" = \\{\\}\"]))", "            emit_line(st, cat([\"local \", tok2, \", \", tval2]))", "            emit_line(st, cat([tok2, \", \", tval2, \" = pcall(function()\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"return \", tnorm]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            emit_line(st, cat([\"if not \", tok2, \" then\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local \", terr2, \" = \", tval2]))", "            emit_line(st, cat([\"local \", thok, \", \", hval2]))", "            emit_line(st, cat([thok, \", \", hval2, \" = pcall(function()\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local error = krt.error_new(\", terr2, \")\"]))", "            emit_line(st, cat([\"local \", thandled, \" = false\"]))", "            bool zfirst = TRUE", "            for h0 in s[triggers]:", "                dict h = h0", "                str zkw = \"if\"", "                if NOT zfirst:", "                    zkw = \"elseif\"", "                str zcond = cat([\"error.cat == \", lua_str(h[cat])])", "                if h.contains(\"cats\"):", "                    list zcnames = h[cats]", "                    list zparts = []", "                    flint zpi = 0", "                    while zpi < len(zcnames):", "                        zparts.add(cat([\"error.cat == \", lua_str(zcnames[zpi])]))", "                        zpi += 1", "                    zcond = zparts.join(\" or \")", "                emit_line(st, cat([zkw, \" \", zcond, \" then\"]))", "                st.add(\"indent\", st[indent] + 1)", "                emit_line(st, cat([thandled, \" = true\"]))", "                emit_stmts(st, h[body])", "                st.add(\"indent\", st[indent] - 1)", "                zfirst = FALSE", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                if zfirst:", "                    emit_line(st, \"if true then\")", "                else:", "                    emit_line(st, \"else\")", "                st.add(\"indent\", st[indent] + 1)", "                emit_line(st, cat([thandled, \" = true\"]))", "                emit_stmts(st, ha[body])", "                st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"if not \", thandled, \" then _G.error(\", terr2, \", 0) end\"]))", "            emit_line(st, cat([\"return \", tnorm]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            emit_line(st, cat([tok2, \", \", tval2, \" = \", thok, \", \", hval2]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_stmts(st, s[\"finally\"])", "            emit_line(st, cat([\"if not \", tok2, \" then _G.error(\", tval2, \", 0) end\"]))", "            emit_line(st, cat([\"if \", tval2, \" ~= \", tnorm, \" then return \", tval2, \" end\"]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"while\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str lid = str(st[loop_id])", "            str cont = cat([\"__continue_\", lid])", "            str brk = cat([\"__break_\", lid])", "            dict wc2 = s[cond]", "            emit_line(st, cat([\"while krt.truthy_strict(\", emit_expr(st, wc2), \") do\"]))", "            st.add(\"indent\", st[indent] + 1)", "            list ls = st[loop_stack]", "            ls.add({cont: cont, brk: brk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", cont, \"::\"]))", "            ls.del(len(ls) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", brk, \"::\"]))", "        elif sk == \"pass\":", "            emit_line(st, \"do end\")", "        elif sk == \"break\":", "            list lsb = st[loop_stack]", "            dict topb = lsb[len(lsb) - 1]", "            emit_line(st, cat([\"goto \", topb[brk]]))", "        elif sk == \"continue\":", "            list lsc = st[loop_stack]", "            dict topc = lsc[len(lsc) - 1]", "            emit_line(st, cat([\"goto \", topc[cont]]))", "        elif sk == \"for\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str fid = str(st[loop_id])", "            str fcont = cat([\"__continue_\", fid])", "            str fbrk = cat([\"__break_\", fid])", "            str fv = s[lua]", "            if s.contains(\"float_fmt\"):", "                dict range_names = st[range_floats]", "                if range_names is NONE:", "                    range_names = {}", "                range_names.add(fv, TRUE)", "                st.add(\"range_floats\", range_names)", "            str fto = cat([\"__to_\", fid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            str form = s[form]", "            if form == \"upto\":", "                emit_line(st, cat([\"local \", fv, \" = 0\"]))", "                dict fte = s[to]", "                emit_line(st, cat([\"local \", fto, \" = \", wrap_flint(emit_expr(st, fte), fte[t], e_nullable(fte))]))", "                emit_line(st, cat([\"while \", fv, \" < \", fto, \" do\"]))", "            else:", "                dict ffe = s[from]", "                dict ftte = s[to]", "                str fstep = cat([\"__step_\", fid])", "                emit_line(st, cat([\"local \", fv, \" = \", wrap_flint(emit_expr(st, ffe), ffe[t], e_nullable(ffe))]))", "                emit_line(st, cat([\"local \", fto, \" = \", wrap_flint(emit_expr(st, ftte), ftte[t], e_nullable(ftte))]))", "                str sx = \"1\"", "                if s.contains(\"step\"):", "                    dict fse = s[step]", "                    sx = wrap_flint(emit_expr(st, fse), fse[t], e_nullable(fse))", "                emit_line(st, cat([\"local \", fstep, \" = \", sx]))", "                emit_line(st, cat([\"while ((\", fstep, \" > 0) and (\", fv, \" < \", fto, \")) or ((\", fstep, \" < 0) and (\", fv, \" > \", fto, \")) do\"]))", "            st.add(\"indent\", st[indent] + 1)", "            list fls = st[loop_stack]", "            fls.add({cont: fcont, brk: fbrk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", fcont, \"::\"]))", "            if form == \"upto\":", "                emit_line(st, cat([fv, \" = \", fv, \" + 1\"]))", "            else:", "                emit_line(st, cat([fv, \" = \", fv, \" + __step_\", fid]))", "            fls.del(len(fls) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", fbrk, \"::\"]))", "        elif sk == \"for_in\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str iid = str(st[loop_id])", "            str icont = cat([\"__continue_\", iid])", "            str ibrk = cat([\"__break_\", iid])", "            str icoll = cat([\"__coll_\", iid])", "            str iidx = cat([\"__i_\", iid])", "            dict ice = s[coll]", "            list inames = s[names]", "            list ilnames = s[lnames]", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            bool list_mode = FALSE", "            str iceb = base_type(ice[t])", "            if iceb == \"list\" OR iceb == \"froz\":", "                list_mode = TRUE", "            elif ice[t] == \"any\" AND len(inames) == 1:", "                list_mode = TRUE", "            if list_mode:", "                str iwrap = \"\"", "                if iceb == \"froz\":", "                    iwrap = wrap_froz(emit_expr(st, ice), ice[t], e_nullable(ice))", "                else:", "                    iwrap = wrap_list(emit_expr(st, ice), ice[t], e_nullable(ice))", "                emit_line(st, cat([\"local \", icoll, \" = \", iwrap]))", "                emit_line(st, cat([\"local \", iidx, \" = 0\"]))", "                emit_line(st, cat([\"while \", iidx, \" < #\", icoll, \" do\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str iv = ilnames[0]", "                emit_line(st, cat([\"local \", iv, \" = \", icoll, \"[\", iidx, \" + 1]\"]))", "            else:", "                emit_line(st, cat([\"local \", icoll, \" = \", wrap_dict(emit_expr(st, ice), ice[t], e_nullable(ice))]))", "                emit_line(st, cat([\"local \", iidx, \" = 0\"]))", "                emit_line(st, cat([\"while \", iidx, \" < #\", icoll, \".keys do\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str ivk = ilnames[0]", "                str ivv = ilnames[1]", "                emit_line(st, cat([\"local \", ivk, \" = \", icoll, \".keys[\", iidx, \" + 1]\"]))", "                emit_line(st, cat([\"local \", ivv, \" = \", icoll, \".vals[\", iidx, \" + 1]\"]))", "            list ils = st[loop_stack]", "            ils.add({cont: icont, brk: ibrk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", icont, \"::\"]))", "            emit_line(st, cat([iidx, \" = \", iidx, \" + 1\"]))", "            ils.del(len(ils) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", ibrk, \"::\"]))", "        elif sk == \"return\":", "            if s.contains(\"expr\"):", "                dict re = s[expr]", "                str rv = coerce_to(emit_expr(st, re), re[t], st[current_ret])", "                if re[t] == \"any\" AND st[current_ret] != \"any\":", "                    rv = checked(rv, re[t], e_nullable(re), st[current_ret])", "                st.add(\"ret_id\", st[ret_id] + 1)", "                str tmp = cat([\"__ret_\", str(st[ret_id])])", "                emit_line(st, cat([\"do local \", tmp, \" = \", rv, \"; return \", tmp, \" end\"]))", "            else:", "                emit_line(st, \"return krt.NONE\")", "        elif sk == \"func\":", "            list fparams = s[params]", "            list fpl = []", "            for fp0 in fparams:", "                dict fp = fp0", "                fpl.add(fp[lua])", "            bool fasyn = s.contains(\"async\")", "            emit_line(st, cat([\"local function \", s[lua], \"(\", fpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            if fasyn:", "                emit_line(st, \"return krt.async_start(function()\")", "                st.add(\"indent\", st[indent] + 1)", "            str saved_ret = st[current_ret]", "            st.add(\"current_ret\", s[ret])", "            list fbody = s[body]", "            emit_hoist(st, collect_scope(fbody))", "            emit_stmts(st, fbody)", "            st.add(\"current_ret\", saved_ret)", "            bool ends_ret = FALSE", "            if len(fbody) > 0:", "                dict flast = fbody[len(fbody) - 1]", "                if flast[k] == \"return\":", "                    ends_ret = TRUE", "            if NOT ends_ret:", "                emit_line(st, \"return krt.NONE\")", "            if fasyn:", "                st.add(\"indent\", st[indent] - 1)", "                emit_line(st, \"end)\")", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        if wrap_ret:", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        st.add(\"cur_pos\", saved)", "        i += 1", "    return \"\"", "", "# ---------- сборка Lua ----------", "", "func generate(dict ast, dict opts) -> str:", "    dict st = {out: [], indent: 0, line_map: [], cur_pos: {}, loop_stack: [], loop_id: 0, try_id: 0, ret_id: 0, current_ret: \"NONE\", range_floats: {}, models: opts[models], futures: {}, future_types: {}}", "    emit_line(st, \"#!/usr/bin/env luajit\")", "    emit_line(st, \"-- generated by kraft\")", "    emit_line(st, cat([\"local __KRAFT_SOURCE = \", lua_str(opts[path])]))", "    emit_line(st, \"local krt = (function()\")", "    list krt_lines = split_lines(opts[krt])", "    for kl in krt_lines:", "        emit_line(st, kl)", "    emit_line(st, \"end)()\")", "", "    list src_lines = split_lines(opts[source])", "    list quoted = []", "    for sl in src_lines:", "        quoted.add(lua_str(sl))", "    emit_line(st, cat([\"krt.SOURCE_PATH = \", lua_str(opts[path])]))", "    emit_line(st, cat([\"krt.SOURCE_LINES = \\{\", quoted.join(\", \"), \"\\}\"]))", "", "    list stdin_lines = opts[stdin]", "    list quoted_stdin = []", "    for stl in stdin_lines:", "        quoted_stdin.add(lua_str(stl))", "    emit_line(st, cat([\"krt.STDIN = \\{\", quoted_stdin.join(\", \"), \"\\}\"]))", "", "    flint map_index = len(st[out]) + 1", "    emit_line(st, \"krt.LINE_MAP = \\{\\}\")", "", "    emit_line(st, \"krt.run(function()\")", "    st.add(\"indent\", 1)", "    if len(opts[prelude]) > 0:", "        list prelude_lines = split_lines(opts[prelude])", "        for pl in prelude_lines:", "            emit_line(st, pl)", "    emit_hoist(st, collect_scope(ast[stmts]))", "    emit_stmts(st, ast[stmts])", "    st.add(\"indent\", 0)", "    emit_line(st, \"end)\")", "", "    list map_parts = []", "    list lm = st[line_map]", "    for m0 in lm:", "        dict m = m0", "        map_parts.add(cat([\"[\", str(m[gen]), \"]=\\{\", str(m[line]), \",\", str(m[col]), \"\\}\"]))", "    list o = st[out]", "    o.replace(map_index - 1, cat([\"krt.LINE_MAP = \\{\", map_parts.join(\",\"), \"\\}\"]))", "    return cat([o.join(\"\\n\"), \"\\n\"])", "", "func extract_stdin(str src) -> list:", "    list out = []", "    list lines = split_lines(src)", "    for l0 in lines:", "        str line = l0", "        flint i = 0", "        flint n = len(line)", "        while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "            i += 1", "        if i < n AND line[i] == \"#\":", "            i += 1", "            while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "                i += 1", "            if line[i..i + 6] == \"stdin:\":", "                i += 6", "                while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "                    i += 1", "                out.add(line[i..n])", "    return out", "", "func write_compiled(str path, str out_lua):", "    str base = path", "    if path.suff(\".kraft\"):", "        base = path[..len(path) - 6]", "    write_file(cat([base, \".lua\"]), out_lua)", "", "# ---------- CLI ----------", "", "list argv = args()", "if len(argv) >= 2 AND argv[1] == \"--version\":", "    show(xkraft 0.9.3)", "    exit(0)", "if len(argv) < 2:", "    show_err(usage: xkraft [--tokens] [-c] file.kraft)", "    exit(1)", "", "func parse_cli(list av, flint start) -> dict:", "    str m = \"run\"", "    flint i = start", "    bool scan = TRUE", "    bool use_prelude = TRUE", "    while scan AND i < len(av):", "        str cur = av[i]", "        flint step = 0", "        if cur == \"--tokens\":", "            m = \"tokens\"", "            step = 1", "        elif cur == \"-c\":", "            m = \"compile\"", "            step = 1", "        elif cur == \"--emit-lua\":", "            m = \"run\"", "            step = 1", "        elif cur == \"--no-prelude\":", "            use_prelude = FALSE", "            step = 1", "        else:", "            scan = FALSE", "        i += step", "    return {mode: m, index: i, prelude: use_prelude}", "", "dict cli = parse_cli(argv, 1)", "str mode = cli.take(\"mode\")", "flint ai = cli.take(\"index\")", "bool use_prelude = cli.take(\"prelude\")", "if ai >= len(argv):", "    show_err(usage: xkraft [--tokens] [-c] file.kraft)", "    exit(1)", "", "str path = argv[ai]", "str src = read_file(path)", "dict lx = lex(src, path)", "if NOT (lx[err] is NONE):", "    dict e = lx[err]", "    e.add(\"path\", path)", "    report_error(e, src)", "    exit(1)", "if mode == \"tokens\":", "    dump_tokens(lx[tokens])", "    exit(0)", "", "